/* notes */

DO $$
BEGIN

    UPDATE driver_deliveries
    SET performance_tier = 'platinum'
    WHERE completed_deliveries >= 50 AND avg_delivery_minutes <= 25.0;

    UPDATE driver_deliveries
    SET performance_tier = 'gold'
    WHERE completed_deliveries >= 30 AND avg_delivery_minutes <= 30.0
        AND performance_tier IS NULL;

    UPDATE driver_deliveries
    SET monthly_bonus = CASE 
            WHEN performance_tier = 'platinum' THEN completed_deliveries * 5.00 
            WHEN performance_tier = 'gold' THEN completed_deliveries * 3.00 
        ELSE monthly_bonus END;

END $$;


SELECT * FROM driver_deliveries ORDER BY driver_id;
